#ifndef EGG_CE_LAYER_H
#define EGG_CE_LAYER_H

#include "twodfx_api.h"

/*
 * Egg CE — dual 2DPT layer proof
 * =================================
 *
 * Start from the host computer with:
 *
 *     OUT 248,206        (206 = CEh)
 *
 * Purpose
 * -------
 * Demonstrates the complete renderer order:
 *
 *     background 2DPT -> sprites 0..63 -> foreground 2DPT
 *
 * It is a practical example for HUDs, cages, masks and other graphics that
 * must appear above sprites while an independent scene remains below them.
 *
 * What appears on screen
 * ----------------------
 * Four colourful face sprites bounce inside a large framed stage. A static
 * grid from the background 2DPT remains behind them. Moving vertical cage bars,
 * an outer frame and two HUD strips are generated by the foreground 2DPT and
 * visibly cover the sprites whenever they overlap.
 *
 * Implementation style
 * --------------------
 * Each 32x32 sprite is generated in a small MCU work buffer and uploaded with
 * twodfx_upload_raw(). The background playlist is built once. Every tick
 * updates the four public sprite definitions and rebuilds only the animated
 * foreground playlist. This egg never touches resource_ram, shadow tables,
 * raw SPBs/2DPBs or private renderer helpers.
 *
 * All tunable resource, artwork, geometry, colour and motion constants live
 * in this header.
 */

/* ------------------------------------------------------------------------- */
/* Sprite resource bank                                                      */
/* ------------------------------------------------------------------------- */

#define EGG_CE_SPRITE_ADDRESS_BASE 0x610000u
#define EGG_CE_SPRITE_WIDTH         32u
#define EGG_CE_SPRITE_HEIGHT        32u
#define EGG_CE_SPRITE_COUNT          4u
#define EGG_CE_SPRITE_ROW_BYTES \
    (EGG_CE_SPRITE_WIDTH / 2u)
#define EGG_CE_SPRITE_BYTES \
    (EGG_CE_SPRITE_ROW_BYTES * EGG_CE_SPRITE_HEIGHT)

#define EGG_CE_TRANSPARENT_COLOUR 0u

/* ------------------------------------------------------------------------- */
/* Profile-specific sprite colours                                           */
/* ------------------------------------------------------------------------- */

#define EGG_CE_EP_SPRITE0_BODY_COLOUR   2u
#define EGG_CE_EP_SPRITE1_BODY_COLOUR   4u
#define EGG_CE_EP_SPRITE2_BODY_COLOUR   5u
#define EGG_CE_EP_SPRITE3_BODY_COLOUR   6u
#define EGG_CE_EP_SPRITE0_ACCENT_COLOUR 7u
#define EGG_CE_EP_SPRITE1_ACCENT_COLOUR 3u
#define EGG_CE_EP_SPRITE2_ACCENT_COLOUR 7u
#define EGG_CE_EP_SPRITE3_ACCENT_COLOUR 1u

#define EGG_CE_TVC_SPRITE0_BODY_COLOUR   3u
#define EGG_CE_TVC_SPRITE1_BODY_COLOUR   5u
#define EGG_CE_TVC_SPRITE2_BODY_COLOUR   9u
#define EGG_CE_TVC_SPRITE3_BODY_COLOUR  11u
#define EGG_CE_TVC_SPRITE0_ACCENT_COLOUR 15u
#define EGG_CE_TVC_SPRITE1_ACCENT_COLOUR  7u
#define EGG_CE_TVC_SPRITE2_ACCENT_COLOUR 13u
#define EGG_CE_TVC_SPRITE3_ACCENT_COLOUR 15u

/* ------------------------------------------------------------------------- */
/* Procedural face artwork                                                   */
/* ------------------------------------------------------------------------- */

#define EGG_CE_FACE_MIN_X  3u
#define EGG_CE_FACE_MAX_X 28u
#define EGG_CE_FACE_MIN_Y  3u
#define EGG_CE_FACE_MAX_Y 28u

#define EGG_CE_LEFT_EYE_X   11u
#define EGG_CE_RIGHT_EYE_X  21u
#define EGG_CE_EYE_MIN_Y    11u
#define EGG_CE_EYE_MAX_Y    14u

#define EGG_CE_MOUTH_MIN_X   12u
#define EGG_CE_MOUTH_MAX_X   21u
#define EGG_CE_MOUTH_Y       22u
#define EGG_CE_MOUTH_CORNER0_X 10u
#define EGG_CE_MOUTH_CORNER1_X 22u
#define EGG_CE_MOUTH_CORNER_Y  21u

#define EGG_CE_ACCENT_PATTERN_MASK 7u
#define EGG_CE_ACCENT_PHASE_STEP   5u

/* ------------------------------------------------------------------------- */
/* Main stage geometry                                                       */
/* ------------------------------------------------------------------------- */

#define EGG_CE_EP_STAGE_X \
    (TWODFX_ENTERPRISE_BASIC_SAFE_MIN_X + EGG_CE_OUTER_FRAME_MARGIN)
#define EGG_CE_EP_STAGE_Y \
    (TWODFX_ENTERPRISE_BASIC_SAFE_MIN_Y - EGG_CE_TOP_HUD_OFFSET_Y)
#define EGG_CE_EP_STAGE_WIDTH  624u
#define EGG_CE_EP_STAGE_HEIGHT 176u

/*
 * TVC composition fits the corrected BASIC safe area including the 8-pixel
 * outer frame and the two 12-pixel HUD strips.
 */
#define EGG_CE_TVC_STAGE_X      134u
#define EGG_CE_TVC_STAGE_Y       73u
#define EGG_CE_TVC_STAGE_WIDTH  496u
#define EGG_CE_TVC_STAGE_HEIGHT 192u

/* ------------------------------------------------------------------------- */
/* Initial sprite motion                                                     */
/* ------------------------------------------------------------------------- */

#define EGG_CE_SPRITE0_INITIAL_X 132
#define EGG_CE_SPRITE0_INITIAL_Y  64
#define EGG_CE_SPRITE0_VELOCITY_X  2
#define EGG_CE_SPRITE0_VELOCITY_Y  1

#define EGG_CE_SPRITE1_INITIAL_X 520
#define EGG_CE_SPRITE1_INITIAL_Y  80
#define EGG_CE_SPRITE1_VELOCITY_X -1
#define EGG_CE_SPRITE1_VELOCITY_Y  1

#define EGG_CE_SPRITE2_INITIAL_X 300
#define EGG_CE_SPRITE2_INITIAL_Y 200
#define EGG_CE_SPRITE2_VELOCITY_X  1
#define EGG_CE_SPRITE2_VELOCITY_Y -2

#define EGG_CE_SPRITE3_INITIAL_X 650
#define EGG_CE_SPRITE3_INITIAL_Y 210
#define EGG_CE_SPRITE3_VELOCITY_X -2
#define EGG_CE_SPRITE3_VELOCITY_Y -1

/* ------------------------------------------------------------------------- */
/* Background 2DPT grid                                                      */
/* ------------------------------------------------------------------------- */

#define EGG_CE_EP_BACKGROUND_FILL_COLOUR  8u
#define EGG_CE_TVC_BACKGROUND_FILL_COLOUR 1u

#define EGG_CE_HORIZONTAL_GRID_FIRST_OFFSET_Y 16u
#define EGG_CE_HORIZONTAL_GRID_STEP_Y         24u
#define EGG_CE_HORIZONTAL_GRID_STROKE          1u
#define EGG_CE_EP_HORIZONTAL_GRID_COLOUR       3u
#define EGG_CE_TVC_HORIZONTAL_GRID_COLOUR      9u

#define EGG_CE_VERTICAL_GRID_FIRST_OFFSET_X 24u
#define EGG_CE_VERTICAL_GRID_STEP_X         48u
#define EGG_CE_VERTICAL_GRID_STROKE          1u
#define EGG_CE_EP_VERTICAL_GRID_COLOUR       4u
#define EGG_CE_TVC_VERTICAL_GRID_COLOUR     13u

#define EGG_CE_STAGE_BORDER_STROKE      3u
#define EGG_CE_EP_STAGE_BORDER_COLOUR   6u
#define EGG_CE_TVC_STAGE_BORDER_COLOUR  7u

/* ------------------------------------------------------------------------- */
/* Animated foreground cage                                                  */
/* ------------------------------------------------------------------------- */

#define EGG_CE_CAGE_PHASE_SHIFT       1u
#define EGG_CE_CAGE_PHASE_MASK       63u
#define EGG_CE_CAGE_FIRST_OFFSET_X   48u
#define EGG_CE_CAGE_STEP_X           64u
#define EGG_CE_CAGE_BAR_WIDTH         8u
#define EGG_CE_CAGE_VERTICAL_MARGIN   8u
#define EGG_CE_EP_CAGE_COLOUR         7u
#define EGG_CE_TVC_CAGE_COLOUR       15u

/* ------------------------------------------------------------------------- */
/* Foreground outer frame and HUD strips                                     */
/* ------------------------------------------------------------------------- */

#define EGG_CE_OUTER_FRAME_MARGIN  8u
#define EGG_CE_OUTER_FRAME_STROKE  4u
#define EGG_CE_EP_OUTER_FRAME_COLOUR   7u
#define EGG_CE_TVC_OUTER_FRAME_COLOUR 15u

#define EGG_CE_HUD_WIDTH  320u
#define EGG_CE_HUD_HEIGHT  12u

#define EGG_CE_TOP_HUD_OFFSET_X   24u
#define EGG_CE_TOP_HUD_OFFSET_Y  -24
#define EGG_CE_BOTTOM_HUD_RIGHT_MARGIN 24u
#define EGG_CE_BOTTOM_HUD_OFFSET_Y     12u

#define EGG_CE_EP_TOP_HUD_COLOUR     5u
#define EGG_CE_EP_BOTTOM_HUD_COLOUR  5u
#define EGG_CE_TVC_TOP_HUD_COLOUR    3u
#define EGG_CE_TVC_BOTTOM_HUD_COLOUR 5u

void egg_CE_layer_start(void);
void egg_CE_layer_tick(void);

#endif /* EGG_CE_LAYER_H */
